WITH images(name,url) AS (VALUES ('Eucalyptus','data:image/jpeg;base64,'),('Eucalyptus Leaves','data:image/jpeg;base64,'),('Fern','data:image/jpeg;base64,'),('Heart','data:image/jpeg;base64,'),('Hydrangea','data:image/jpeg;base64,'),('Mini Daisies','data:image/jpeg;base64,'),('Snake Leaves','data:image/jpeg;base64,'),('Spirals','data:image/jpeg;base64,'),('Pecan','data:image/jpeg;base64,'),('Olfersea','data:image/jpeg;base64,')) UPDATE public.fillers f SET image_url=i.url FROM images i WHERE f.name=i.name RETURNING f.name;